import CmsImageField from '@/components/feature/CmsImageField';
import CmsRichTextField from '@/components/feature/CmsRichTextField';
import { adminToast } from '@/lib/adminToast';

export type CmsStoryItem = {
  tag: string;
  title: string;
  description: string;
  image: string;
};

export default function CmsStoriesList({
  stories,
  onChange,
}: {
  stories: CmsStoryItem[];
  onChange: (next: CmsStoryItem[]) => void;
}) {
  const update = (index: number, patch: Partial<CmsStoryItem>) => {
    onChange(stories.map((story, i) => (i === index ? { ...story, ...patch } : story)));
  };

  const addStory = () => {
    onChange([...stories, { tag: '', title: '', description: '', image: '' }]);
    adminToast.added();
  };

  const removeStory = (index: number) => {
    onChange(stories.filter((_, i) => i !== index));
    adminToast.deleted();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <p className="text-sm font-semibold text-slate-700">
          Stories
          <span className="ml-2 text-xs font-normal text-slate-400">{stories.length} items</span>
        </p>
        <button
          type="button"
          onClick={addStory}
          className="flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-[#2879b1] bg-[#2879b1]/10 hover:bg-[#2879b1]/20 rounded-lg cursor-pointer"
        >
          <i className="ri-add-line"></i>
          Add story
        </button>
      </div>

      {stories.length === 0 && (
        <p className="text-sm text-slate-500 border border-dashed border-slate-200 rounded-lg p-6 text-center">
          No stories yet. Click Add story to create one.
        </p>
      )}

      {stories.map((story, index) => (
        <div key={index} className="border border-slate-200 rounded-xl overflow-hidden">
          <div className="px-4 py-3 bg-slate-50 flex items-center justify-between gap-3">
            <span className="text-sm font-semibold text-slate-800 truncate">
              Story {index + 1}
              {story.title ? ` — ${story.title}` : ''}
            </span>
            <button
              type="button"
              onClick={() => removeStory(index)}
              className="text-xs font-medium text-red-600 hover:text-red-700 cursor-pointer whitespace-nowrap"
            >
              Delete
            </button>
          </div>
          <div className="p-4 space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Tag</label>
                <input
                  type="text"
                  value={story.tag || ''}
                  onChange={(e) => update(index, { tag: e.target.value })}
                  placeholder="e.g. Milestone"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#2879b1]/20 focus:border-[#2879b1]"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Title</label>
                <input
                  type="text"
                  value={story.title || ''}
                  onChange={(e) => update(index, { title: e.target.value })}
                  placeholder="Story title"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#2879b1]/20 focus:border-[#2879b1]"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Description</label>
              <CmsRichTextField
                value={story.description || ''}
                onChange={(description) => update(index, { description })}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Image (upload or paste URL)</label>
              <CmsImageField
                value={story.image || ''}
                onChange={(image) => update(index, { image })}
              />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
